macro_rules! compare_synthetic_generics {
    () => {
        fn compare_synthetic_generics < 'tcx > (tcx : TyCtxt < 'tcx > , impl_m : ty :: AssocItem , trait_m : ty :: AssocItem , delay : bool ,) -> Result < () , ErrorGuaranteed > { let mut error_found = None ; let impl_m_generics = tcx . generics_of (impl_m . def_id) ; let trait_m_generics = tcx . generics_of (trait_m . def_id) ; let impl_m_type_params = impl_m_generics . own_params . iter () . filter_map (| param | match param . kind { GenericParamDefKind :: Type { synthetic , .. } => Some ((param . def_id , synthetic)) , GenericParamDefKind :: Lifetime | GenericParamDefKind :: Const { .. } => None , }) ; let trait_m_type_params = trait_m_generics . own_params . iter () . filter_map (| param | match param . kind { GenericParamDefKind :: Type { synthetic , .. } => Some ((param . def_id , synthetic)) , GenericParamDefKind :: Lifetime | GenericParamDefKind :: Const { .. } => None , }) ; for ((impl_def_id , impl_synthetic) , (trait_def_id , trait_synthetic)) in iter :: zip (impl_m_type_params , trait_m_type_params) { if impl_synthetic != trait_synthetic { let impl_def_id = impl_def_id . expect_local () ; let impl_span = tcx . def_span (impl_def_id) ; let trait_span = tcx . def_span (trait_def_id) ; let mut err = struct_span_code_err ! (tcx . dcx () , impl_span , E0643 , "method `{}` has incompatible signature for trait" , trait_m . name ()) ; err . span_label (trait_span , "declaration in trait here") ; if impl_synthetic { err . span_label (impl_span , "expected generic parameter, found `impl Trait`") ; let _ : Option < _ > = try { let new_name = tcx . opt_item_name (trait_def_id) ? ; let trait_m = trait_m . def_id . as_local () ? ; let trait_m = tcx . hir_expect_trait_item (trait_m) ; let impl_m = impl_m . def_id . as_local () ? ; let impl_m = tcx . hir_expect_impl_item (impl_m) ; let new_generics_span = tcx . def_ident_span (impl_def_id) ? . shrink_to_hi () ; let generics_span = impl_m . generics . span . substitute_dummy (new_generics_span) ; let new_generics = tcx . sess . source_map () . span_to_snippet (trait_m . generics . span) . ok () ? ; err . multipart_suggestion ("try changing the `impl Trait` argument to a generic parameter" , vec ! [(impl_span , new_name . to_string ()) , (generics_span , new_generics) ,] , Applicability :: MaybeIncorrect ,) ; } ; } else { err . span_label (impl_span , "expected `impl Trait`, found generic parameter") ; let _ : Option < _ > = try { let impl_m = impl_m . def_id . as_local () ? ; let impl_m = tcx . hir_expect_impl_item (impl_m) ; let (sig , _) = impl_m . expect_fn () ; let input_tys = sig . decl . inputs ; struct Visitor (hir :: def_id :: LocalDefId) ; impl < 'v > intravisit :: Visitor < 'v > for Visitor { type Result = ControlFlow < Span > ; fn visit_ty (& mut self , ty : & 'v hir :: Ty < 'v , AmbigArg >) -> Self :: Result { if let hir :: TyKind :: Path (hir :: QPath :: Resolved (None , path)) = ty . kind && let Res :: Def (DefKind :: TyParam , def_id) = path . res && def_id == self . 0 . to_def_id () { ControlFlow :: Break (ty . span) } else { intravisit :: walk_ty (self , ty) } } } let span = input_tys . iter () . find_map (| ty | Visitor (impl_def_id) . visit_ty_unambig (ty) . break_value ()) ? ; let bounds = impl_m . generics . bounds_for_param (impl_def_id) . next () ? . bounds ; let bounds = bounds . first () ? . span () . to (bounds . last () ? . span ()) ; let bounds = tcx . sess . source_map () . span_to_snippet (bounds) . ok () ? ; err . multipart_suggestion ("try removing the generic parameter and using `impl Trait` instead" , vec ! [(impl_m . generics . span , String :: new ()) , (span , format ! ("impl {bounds}")) ,] , Applicability :: MaybeIncorrect ,) ; } ; } error_found = Some (err . emit_unless_delay (delay)) ; } } if let Some (reported) = error_found { Err (reported) } else { Ok (()) } }
    };
}

compare_synthetic_generics!();